// Referência IA: pilhas estáticas em nove posições discretas. Nenhuma física dinâmica.
export const AREA_PER_KG=180,MAX_HEIGHT=200;
export function dimensions(w){const area=AREA_PER_KG*w.mass,ratio=w.ratio??1.2;const width=Math.sqrt(area*ratio*(w.shape==='triangle'?2:1));return {width,height:width/ratio,area};}
export function stacks(weights){const cols=new Map();weights.forEach((w,i)=>{if(!cols.has(w.x))cols.set(w.x,[]);cols.get(w.x).push(i);});for(const ids of cols.values())ids.sort((a,b)=>(weights[a].order??a)-(weights[b].order??b));return cols;}
export function layout(weights){const out=[];for(const [x,ids] of stacks(weights)){let h=0;for(const i of ids){const d=dimensions(weights[i]);out[i]={...d,x:400+x*80,bottom:253-h,top:253-h-d.height};h+=d.height;}}return out;}
export function legal(weights){for(const w of weights){const d=dimensions(w);if(!Number.isFinite(w.mass)||w.mass<1||w.mass>6||!Number.isInteger(w.x)||Math.abs(w.x)>4||d.width>72)return 'Posição ou tamanho fora dos limites.';}for(const ids of stacks(weights).values()){let h=0;for(let j=0;j<ids.length;j++){const w=weights[ids[j]];h+=dimensions(w).height;if(w.shape==='triangle'&&j<ids.length-1)return 'Triângulos não podem sustentar outro bloco.';}if(h>MAX_HEIGHT)return 'A pilha ultrapassaria a altura máxima.';}return '';}
export function movable(weights,i){const w=weights[i];if(w.fixed)return 'Este bloco é fixo.';const ids=stacks(weights).get(w.x);return ids.at(-1)!==i?'Retire primeiro os blocos de cima. O suporte não pode ser movido.':'';}
export function moveBlock(weights,i,x){const reason=movable(weights,i);if(reason)return {ok:false,reason,weights};if(x===weights[i].x)return {ok:true,weights};if(!Number.isInteger(x)||Math.abs(x)>4)return {ok:false,reason:'Escolha uma posição inteira de -4 a 4.',weights};const dest=stacks(weights).get(x)??[];if(dest.length&&weights[dest.at(-1)].shape==='triangle')return {ok:false,reason:'Topo triangular: colocação rejeitada. O bloco ficou na posição anterior.',weights};const next=structuredClone(weights);next[i].x=x;next[i].order=Math.max(...weights.map((w,j)=>w.order??j))+1;const error=legal(next);return error?{ok:false,reason:error,weights}:{ok:true,weights:next};}
export function editBlock(weights,i,patch){const reason=movable(weights,i);if(reason)return {ok:false,reason,weights};const next=structuredClone(weights);Object.assign(next[i],patch);const error=legal(next);return error?{ok:false,reason:error,weights}:{ok:true,weights:next};}
